WFJ.Data.add("gossip", {
  ["fa030e6615102537"] = { "Inconcepibile!", "." },
  ["fa042aff0791599d"] = { "Prima di condividere i miei doni con te, mi serve una dimostrazione della tua determinazione...", "." },
  ["fa0b8880d050efcb"] = { "I miei esploratori riferiscono che la ⟦Syndicate=Lega dei Tagliagole⟧ si è stabilita in una grotta nascosta sull'altopiano orientale. Sii prudente quando ti avventuri in quella zona.", "." },
  ["fa0bd7d0aed1139c"] = { "Questo lavoro non è per i deboli di cuore. Ho uno zio che ha perso una mano! Povero vecchio Stumpy... comunque, se ti interessa ancora, forse posso mostrarti un paio di cose.", "." },
  ["fa0c05b5c54152c7"] = { "Se cerchi un volo per tornare a ⟦Rut'theran Village=Rut'theran⟧, dovresti parlare con la mia collega elfa della notte, Silva Fil'naveth.", "." },
  ["fa17a08e73d080fd"] = { "Il piccoletto si nasconde in una di quelle casse, compare. Buona fortuna!", "." },
  ["fa1808ece019746d"] = { "Non c'è modo che tu esca da qui sulle tue gambe!", "." },
  ["fa21814ed4946529"] = { "MMmmMMmmm. Ha un profumo delizioso, Khara.", "." },
  ["fa221fc39dcc5e0f"] = { "La Banca di ⟦Stormwind=Roccavento⟧ si trova nel ⟦Trade District=Quartiere del Commercio⟧, appena a nord-ovest delle porte della città. Ecco, te la mostro sulla mappa.", "." },
  ["fa2af3ebc4c53994"] = { "%s sorride.", "." },
  ["fa35e7cd9081a772"] = { "Sono responsabile delle attività di Shen'dar Village, e ci sono un sacco di cose da tenere d'occhio qui intorno. Tra banditi, cultisti e altri imprevisti che saltano fuori, mandare avanti questo villaggio è un bel lavoro.", "." },
  ["fa373a61d7078e3c"] = { "Molte prove attendono un paladino della Luce, {name}. Sappi che le nostre strade si incroceranno molte volte in futuro, se manterrai la tua passione e resterai fedele alle virtù che lodiamo.", "." },
  ["fa38ffb5cf795ff7"] = { "Se ti metti acqua di colonia o profumo, vedrai chi è innamorato. Sono quelli che accettano i pegni d'amore... e offrono un regalo in cambio.\n\nMa ricorda: per dare un pegno d'amore a qualcuno, devi avere l'odore giusto! Gli uomini amano il profumo, mentre le donne preferiscono l'acqua di colonia.", "." },
  ["fa3f646b858062de"] = { "{name}, sei <pronto/pronta> per il compito supremo. Le rune infuocate incise sul pavimento del Nucleo Ardente sono condotti verso il reame del fuoco, e la loro presenza è al tempo stesso un affronto per noi e una fonte di potere per i Signori del Fuoco. Vanno estinte!\n\nPer estinguere una runa, prendi una fiala di Quintessenza Acquea. Versala sulla runa e la sua fiamma si spegnerà, rendendola inutile e indebolendo il nostro nemico!", "." },
  ["fa4b548e6cfa6e4e"] = { "Vuoi imparare dal maestro, eh?", "." },
  ["fa5033c55ca17b42"] = { "Opzione del mercante", "." },
  ["fa51aa5678db0954"] = { "Perché dovrei prendermi la briga di riparare la trappola? Perché non eliminare la guardia alla vecchia maniera?", "." },
  ["fa5255d44debb58a"] = { "In verità, {name}, ho paura... Paura che il tuo arrivo, tutto questo, sia solo il frutto di una mente squilibrata. Riesci a immaginare che tortura sia? Io... Ti prego, devi fare presto.", "." },
  ["fa5f4fe497b17631"] = { "Vediamo... quattordici più sette, riporto due... oh, sì?", "." },
  ["fa61a3c093e1971c"] = { "Non lasciarmi morire!", "." },
  ["fa66496542f847fe"] = { "Sogni?", "." },
  ["fa6ee2b2b8b93afb"] = { "%s corre dagli altri operai del ponte, ansimando.", "." },
  ["fa708549b595ec43"] = { "Ehi! Che succede?", "." },
  ["fa722cfa8b32e5fe"] = { "Grazie! Grazie, <sacerdote/sacerdotessa>. Ora posso affrontare quei wendigo con la Luce dalla mia parte!", "." },
  ["fa7470b7748fc6a3"] = { "Le creature di ⟦Winterspring=Fontefredda⟧ sono un buon punto da cui cominciare.\n\nPerò potrebbero esserci anche altri posti dove cercare...", "." },
  ["fa78256740d0265c"] = { "Muori nel nome di Edwin Van Cleef!", "." },
  ["fa7b202d074b641b"] = { "Pensare lui in Royal Quarter. ⟦Kurden Bloodclaw=Kurden Graffiasangue⟧ essere piccolo orco.", "." },
  ["fa7c08639381673c"] = { "Il generale dei Piccatonante è caduto! La battaglia è vinta!\n\nOra ridi, mentre l'⟦Alliance=Alleanza⟧ si affanna a recuperare i possedimenti perduti.", "." },
  ["fa8502c6383fe520"] = { "Se il capitano lo scopre, per me è finita.", "." },
  ["fa927e8dd793b11d"] = { "Che cattivone! Chi ti ha messo su?", "." },
  ["fa9452f5b9603d29"] = { "Frantuma l'artiglio morto e contorto.", "." },
  ["fa9dfb70db881b31"] = { "Cos'hai lì, {name}?\n\n<Malyfous indica i Guanti Lunghi a Piastre Compatte che spuntano dal tuo zaino.>", "." },
  ["fab4a730c53dcca7"] = { "Sì?\n\nMmm. Ho la sensazione di sapere cosa stai per chiedermi: cosa spinge qualcuno a vivere qui fuori, nella parte più remota delle ⟦Barrens=Savane⟧, con la minaccia dei verrospini tutt'intorno e senza alcuna protezione? Be', abbiamo tutti le nostre ragioni per giustificare il nostro modo di agire. La vera domanda è: cosa porta <un/una> semplice {race} nelle zone più remote delle ⟦Barrens=Savane⟧ a parlare con una donna che chiaramente non si cura della propria incolumità?\n\nScommetto che la risposta la conosciamo entrambi.", "." },
  ["fab53a0e24d9a723"] = { "Mi fa piacere rivederti, <dottor/dottoressa> {name}. Ho seguito i tuoi progressi e oserei dire che è ora che tu impari alcune delle tecniche di bendaggio più avanzate.\n\nTorna da me di tanto in tanto, man mano che la tua abilità cresce, e ti insegnerò tutto ciò che so.", "." },
  ["faba5c25e517b848"] = { "Nat, voglio comprare le tue Esche per Fanguzzola!", "." },
  ["fac9c38c1f8c1b69"] = { "Proteggete lo stormo! Questi intrusi muoiono ora!", "." },
  ["face2b8ff71d77fb"] = { "Cogli il frutto dal drago della notte.", "." },
  ["fad595865848ccc6"] = { "In questa zona vivono molte creature considerate alleate degli elfi della notte. Gli elfi hanno avuto accesso al potere racchiuso in ognuna di queste creature: è tempo che anche all'Orda sia concessa la stessa soddisfazione. Ho escogitato un modo per catturare questo potere e usarlo a nostro vantaggio.\n\nNon dubitare di ciò che ti dico, {name}. Aiutami, e vedrai che dico la verità.", "." },
  ["fad76b2e0a9fef42"] = { "<Il sommo inquisitore Fairbanks scuote la testa.>\n\nNo, {race}: solo uno dei suoi figli è morto. L'altro vive...\n\n<Il sommo inquisitore Fairbanks indica il cielo.>\n\nLe ⟦Outland=Terre Esterne⟧... Cercalo là...", "." },
  ["faea9e7f7efcc84c"] = { "Se ti servono i documenti per fondare una gilda, devi salire a ⟦Ironforge=Forgiardente⟧ e passare dal Visitor's Center di ⟦Ironforge=Forgiardente⟧.", "." },
  ["faec692b9aeead70"] = { "Hai fatto un lavoro eccezionale, soldato! La cavalleria è pronta a partire al tuo comando.", "." },
  ["fafa57c32d068858"] = { "%s fa un sorrisetto.", "." },
  ["fafb34290aba1a3c"] = { "Il Dun Baldar South Bunker protegge i fianchi meridionale e orientale di Dun Baldar.\n\nÈ controllato dall'⟦Alliance=Alleanza⟧.", "." },
  ["fafd3489ddebcb04"] = { "Le ceneri dell'Uomo di Paglia in fiamme irradiano un potere magico. Le ceneri ce le hai già sul viso.", "." },
})
